{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "All clinical trial registrations either being planned, or currently underway to diagnose, treat or prevent COVID-19 were eligible for inclusion in the baseline results of this review. This included patients known to be infected with COVID-19 as well as healthy volunteers, healthcare workers or other patient populations where health related outcomes were assessed in the context of COVID-19. The review was not limited by outcome, language or intervention given the desire to capture all clinical trial registrations planning to or currently evaluating any COVID-19 diagnostic, prevention or treatment modality. Eligibility was not restricted to clinical trials only; no limitations on study design were applied so that all research and observational studies would be incorporated, including retrospective studies.",
      "reason": "The eligibility paragraph explicitly lists the types of records eligible (clinical trial registrations planned or underway), populations (infected patients, healthy volunteers, healthcare workers, other patient populations), and states no limitations on outcomes or study design—thus specifying study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The review was not limited by outcome, language or intervention given the desire to capture all clinical trial registrations planning to or currently evaluating any COVID-19 diagnostic, prevention or treatment modality. All trial registry records included in the review are hereafter referred to as clinical 'study' registrations.",
      "reason": "The methods explicitly state the review was not limited by language and specify the report type included (trial registry records/clinical study registrations), indicating eligibility by report characteristic and limiting to registry records rather than, for example, published articles."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the provided text distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "The most common registered study design identified was randomised control trial (RCT), with 294 studies identified (Figure 2A). Other study designs frequently identified were: case series (N=109), non-randomised interventional studies (N=105), and cohort studies (N=98). ... In total 29 (4%) studies did not contain sufficient information in the registry to determine the study design.",
      "reason": "The manuscript specifies groups used in synthesis (study design categories and intervention types as presented in figures/tables), but it does not explicitly link these groups to prespecified comparisons defined in the review objectives in the provided evidence, so the requirement is only partially met."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The review was not limited by outcome, language or intervention given the desire to capture all clinical trial registrations planning to or currently evaluating any COVID-19 diagnostic, prevention or treatment modality.",
      "reason": "A rationale is provided explaining the notable restriction choices (e.g., not limiting by language/outcome/intervention) based on the intent to capture all relevant registrations; this constitutes an explicit rationale for eligibility restrictions."
    }
  ],
  "confidence": 80
}

